          rowHeight={60}
          showGridLines
          transformScale={transformScale}
          useCssTransforms={useCssTransforms}
        >
          {layout.map((item) => (
            <GridItem i={item.i} key={item.i}>
              <div className="example-item">{item.i}</div>
            </GridItem>
          ))}
        </GridLayout>
      </div>

      <p className="demo-description">
