  readonly infinity = Infinity;
  maxRowsEnabled = false;
  restoreOnDrag = false;
  distributeEvenly = false;
  transformScale = 1;
  useCssTransforms = true;
  layout: TLayout = initialLayout;
  positioningMechanism = '';

